-- Add eleven-a-side formations, retaining all five-a-side saves and existing family RLS.
alter table public.player_squads drop constraint player_squads_formation_check;
alter table public.player_squads add constraint player_squads_formation_check check(formation in ('diamond','box','4-3-3','4-4-2','4-2-3-1'));
alter table public.player_squads drop constraint player_squads_footballers_check;
alter table public.player_squads add constraint player_squads_footballers_check check(
 cardinality(footballers)=case when formation in ('diamond','box') then 5 else 11 end
 and array_ndims(footballers)=1 and array_lower(footballers,1)=1
);
create or replace function star_private.validate_player_squad() returns trigger language plpgsql set search_path='' as $$
declare expected integer;selected text;keepers text[]:=array['brosnan','kop','roebuck','hampton','yamashita','tullis-joyce','sophie-baggaley','chiamaka-nnadozie','sophie-whitehouse','shae-yanez','khiara-keating','mary-earps','constance-picaud','daphne-van-domselaar','pauline-peyraud-magnin','fran-bentley','kirstie-levell','anna-king','lysianne-proulx','olivia-clark','anna-tamminen','katie-cox','sian-rogers','grace-moloney','frances-stenson','safia-middleton-patel','alex-brooks'];roster text[]:=array['hemp','blindkilde','kelly','caldentey','walsh','carpenter','fisk','brosnan','koga','stanway','kop','roebuck','asllani','godfrey','tierney','goodwin','hampton','yamashita','tullis-joyce','williamson','fox','bronze','greenwood','le-tissier','little','cuthbert','hasegawa','toone','kirby','kendall','russo','james','shaw','terland','seike','daly','anna-patten','lynn-wilms','missy-bo-kearns','sophie-baggaley','millie-turner','neve-herron','lisa-naalsund','lily-crosthwaite','veatriki-sarri','chiamaka-nnadozie','marisa-olislagers','maisie-symonds','madison-haley','sophie-whitehouse','ellie-mason','kiera-skeels','jodie-hutton','lucy-fitzgerald','gillian-kenney','shae-yanez','allyson-swaby','aimee-everett','annabel-blanchard','ashleigh-weerden','bethany-england','ruby-mace','mayumi-pacheco','clare-wheeler','yuka-momiki','ornella-vignola','khiara-keating','jenna-clark','fuka-nagano','ceri-holland','beata-olsson','mary-earps','maria-leon','alexia-putellas','kadidiatou-diani','anna-sandberg','jessica-park','amanda-nilden','olivia-holdt','jessica-naz','cathinka-tandberg','constance-picaud','estelle-cascarino','ffion-morgan','katie-zelem','riko-ueki','ebony-salmon','asmita-ale','daphne-van-domselaar','sjoeke-nusken','vivianne-miedema','kirsty-hanson','caitlin-hayes','hikaru-kitagawa','mia-enderby','grace-geyoro','rebeca-bernal','noelle-maritz','lotte-wubben-moy','drew-spence','seraina-piubel','danielle-van-de-donk','shannon-cooke','pauline-peyraud-magnin','elisha-n-dow','aoba-fujino','aggie-beever-jones','aurora-galli','naomi-girma','hinata-miyazawa','olivia-smith','victoria-pelova','maelys-mpome','megan-finnigan','simone-magill','kirsty-howat','rebecca-knaak','nikita-parris','fran-bentley','brooke-aspin','ella-powell','marine-dafeur','lotta-lindstrom','kirstie-levell','maddi-wilde','jamie-finn','rachel-williams','charlie-wellings','anna-king','emma-brown','beth-hepple','lucy-watson','olivia-fergusson','lysianne-proulx','jorja-fox','jenna-slattery','mary-mcateer','princess-ademiluyi','olivia-clark','olivia-mcloughlin','poppy-pritchard','alisha-lehmann','anna-tamminen','demi-stokes','jordan-nobbs','beth-lumsden','katie-cox','chloe-mustaki','codie-thomas','tove-almqvist','aimee-claypole','sian-rogers','chloe-warrington','tilly-bristow','halle-houssein','ava-baker','grace-moloney','amy-goddard','lilly-mitchell','emma-harries','maria-edwards','frances-stenson','rhiannon-roberts','chloe-paxton','katie-kitching','izzy-atkinson','safia-middleton-patel','eden-skyers','poppy-wilson','madison-perry','alex-brooks','tara-ohanlon','melissa-lawley','chloe-williams','yana-daniels'];
begin
 if tg_op='UPDATE' and new.player_id<>old.player_id then raise exception 'A squad stays with its player' using errcode='23514';end if;
 expected:=case when new.formation in ('diamond','box') then 5 when new.formation in ('4-3-3','4-4-2','4-2-3-1') then 11 else null end;
 if expected is null then raise exception 'Choose a formation' using errcode='23514';end if;
 if new.footballers is null or cardinality(new.footballers)<>expected or (select count(distinct p) from unnest(new.footballers) p)<>expected then raise exception 'Choose % different players',expected using errcode='23514';end if;
 foreach selected in array new.footballers loop
  if selected is null or not(selected=any(roster)) then raise exception 'Choose a player from the roster' using errcode='23514';end if;
 end loop;
 if not(new.footballers[1]=any(keepers)) or exists(select 1 from unnest(new.footballers[2:expected]) p where p=any(keepers)) then raise exception 'Choose one goalkeeper and % outfield players',expected-1 using errcode='23514';end if;
 if not(new.captain=any(new.footballers)) then raise exception 'Choose a captain from your squad' using errcode='23514';end if;
 new.name:=btrim(new.name);new.updated_at:=now();return new;
end $$;
notify pgrst,'reload schema';
